/*
Modelo físico ideal - SIADL - PowerDesigner / SQL Server 2025
Alias utilizado: SDL (substituir pelo alias oficial se necessário)
Observação: Script de referência para reverse engineering no PowerDesigner. Ajustes finais de filegroups,
partições, compressão e parâmetros de armazenamento devem ser homologados pela ABD.
*/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- Infraestrutura de particionamento mensal para tabelas transacionais/históricas massivas.
IF NOT EXISTS (SELECT 1 FROM sys.partition_functions WHERE name = 'PF_SDL_MENSAL')
BEGIN
    CREATE PARTITION FUNCTION PF_SDL_MENSAL (DATETIME2(3))
    AS RANGE RIGHT FOR VALUES
    ('2026-01-01','2026-02-01','2026-03-01','2026-04-01','2026-05-01','2026-06-01',
     '2026-07-01','2026-08-01','2026-09-01','2026-10-01','2026-11-01','2026-12-01',
     '2027-01-01');
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.partition_schemes WHERE name = 'PS_SDL_MENSAL')
BEGIN
    CREATE PARTITION SCHEME PS_SDL_MENSAL AS PARTITION PF_SDL_MENSAL ALL TO ([PRIMARY]);
END;
GO


IF NOT EXISTS (SELECT 1 FROM sys.partition_functions WHERE name = 'PF_SDL_MENSAL_DATA')
BEGIN
    CREATE PARTITION FUNCTION PF_SDL_MENSAL_DATA (DATE)
    AS RANGE RIGHT FOR VALUES
    ('2026-01-01','2026-02-01','2026-03-01','2026-04-01','2026-05-01','2026-06-01',
     '2026-07-01','2026-08-01','2026-09-01','2026-10-01','2026-11-01','2026-12-01',
     '2027-01-01');
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.partition_schemes WHERE name = 'PS_SDL_MENSAL_DATA')
BEGIN
    CREATE PARTITION SCHEME PS_SDL_MENSAL_DATA AS PARTITION PF_SDL_MENSAL_DATA ALL TO ([PRIMARY]);
END;
GO


