-- ==============================================================
-- Tabela: SDLTB001_CLIENTE (CLIENTE)
-- Armazena a identificação cadastral do cliente pessoa física ou jurídica atendido pelo SIADL, com situação, segmento e dados mínimos necessários à vinculação com contas, atendimentos e dispositivos.
-- ==============================================================
CREATE TABLE [dbo].[SDLTB001_CLIENTE] (
    [NU_CLIENTE] BIGINT IDENTITY(1,1) NOT NULL,
    [NO_CLIENTE] VARCHAR(150) NOT NULL,
    [NU_CPF_CNPJ] CHAR(14) NOT NULL,
    [IC_TIPO_PESSOA] CHAR(1) NOT NULL,
    [DH_CADASTRO] DATETIME2(3) NOT NULL,
    [CO_SITUACAO_CLIENTE] TINYINT NOT NULL,
    [CO_SEGMENTO_CLIENTE] TINYINT NOT NULL,
    [DH_INCLUSAO_REGISTRO] DATETIME2(3) NOT NULL CONSTRAINT [DF_SDLTB001_DH_INCLUSAO_REGIST] DEFAULT (SYSDATETIME()),
    [DH_ALTERACAO_REGISTRO] DATETIME2(3) NULL,
    [CO_USUARIO_INCLUSAO] VARCHAR(20) NULL,
    [CO_USUARIO_ALTERACAO] VARCHAR(20) NULL,
    [VS_CONTROLE_CONCORRENCIA] ROWVERSION NOT NULL,
    CONSTRAINT [PK_SDLTB001] PRIMARY KEY CLUSTERED ([NU_CLIENTE]),
    CONSTRAINT [CC_SDLTB001_1] CHECK (NU_CPF_CNPJ NOT LIKE '%[^0-9]%'),
    CONSTRAINT [CC_SDLTB001_2] CHECK (IC_TIPO_PESSOA IN ('F','J'))
);
GO

