-- ==============================================================
-- Tabela: SDLTB008_DISPOSITIVO_CLIENTE (DISPOSITIVO_CLIENTE)
-- Armazena dispositivo vinculado ao cliente para uso em autenticação, segurança e antifraude, com tipo, sistema operacional, hash e situação.
-- ==============================================================
CREATE TABLE [dbo].[SDLTB008_DISPOSITIVO_CLIENTE] (
    [NU_DISPOSITIVO_CLIENTE] BIGINT IDENTITY(1,1) NOT NULL,
    [NU_CLIENTE] BIGINT NOT NULL,
    [CO_TIPO_DISPOSITIVO] TINYINT NOT NULL,
    [CO_SISTEMA_OPERACIONAL] TINYINT NULL,
    [CO_HASH_DISPOSITIVO] CHAR(64) NOT NULL,
    [DT_VINCULO] DATE NOT NULL,
    [DT_REVOGACAO] DATE NULL,
    [IC_DISPOSITIVO_ATIVO] CHAR(1) NOT NULL CONSTRAINT [DF_SDLTB008_IC_DISPOSITIVO_ATI] DEFAULT ('S'),
    [DH_INCLUSAO_REGISTRO] DATETIME2(3) NOT NULL CONSTRAINT [DF_SDLTB008_DH_INCLUSAO_REGIST] DEFAULT (SYSDATETIME()),
    [DH_ALTERACAO_REGISTRO] DATETIME2(3) NULL,
    [CO_USUARIO_INCLUSAO] VARCHAR(20) NULL,
    [CO_USUARIO_ALTERACAO] VARCHAR(20) NULL,
    CONSTRAINT [PK_SDLTB008] PRIMARY KEY CLUSTERED ([NU_DISPOSITIVO_CLIENTE]),
    CONSTRAINT [CT_SDLTB008_DT_REVOGACAO] CHECK (DT_REVOGACAO IS NULL OR DT_REVOGACAO >= DT_VINCULO),
    CONSTRAINT [CC_SDLTB008_1] CHECK (IC_DISPOSITIVO_ATIVO IN ('S','N'))
);
GO

-- ==============================================================
-- Tabela: SDLTB009_LIMITE_CONTA (LIMITE_CONTA)
-- Armazena limites operacionais por conta e tipo de limite, com vigência negocial controlada por datas de início e fim.
-- ==============================================================
CREATE TABLE [dbo].[SDLTB009_LIMITE_CONTA] (
    [DT_INICIO_VIGENCIA] DATE NOT NULL,
    [NU_LIMITE_CONTA] BIGINT IDENTITY(1,1) NOT NULL,
    [NU_CONTA] BIGINT NOT NULL,
    [CO_TIPO_LIMITE] TINYINT NOT NULL,
    [VR_LIMITE] DECIMAL(17,2) NOT NULL,
    [DT_FIM_VIGENCIA] DATE NULL,
    [DH_INCLUSAO_REGISTRO] DATETIME2(3) NOT NULL CONSTRAINT [DF_SDLTB009_DH_INCLUSAO_REGIST] DEFAULT (SYSDATETIME()),
    [DH_ALTERACAO_REGISTRO] DATETIME2(3) NULL,
    [CO_USUARIO_INCLUSAO] VARCHAR(20) NULL,
    [CO_USUARIO_ALTERACAO] VARCHAR(20) NULL,
    [VS_CONTROLE_CONCORRENCIA] ROWVERSION NOT NULL,
    CONSTRAINT [PK_SDLTB009] PRIMARY KEY CLUSTERED ([DT_INICIO_VIGENCIA], [NU_LIMITE_CONTA]),
    CONSTRAINT [CC_SDLTB009_1] CHECK (VR_LIMITE >= 0),
    CONSTRAINT [CT_SDLTB009_DT_FIM_VIGENCIA] CHECK (DT_FIM_VIGENCIA IS NULL OR DT_FIM_VIGENCIA > DT_INICIO_VIGENCIA)
) ON [PS_SDL_MENSAL_DATA]([DT_INICIO_VIGENCIA]);
GO

